recipes.code:
{
  "inputs": [
    {
      "id": "umtri-api-token",
      "type": "promptString",
      "description": "Personal access token from app.umtri.io → Settings → API Tokens. Read tokens cannot call write tools.",
      "password": true
    }
  ],
  "servers": {
    "umtri": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "umtri-mcp@1.1.0"
      ],
      "env": {
        "UMTRI_API_TOKEN": "${input:umtri-api-token}",
        "UMTRI_API_BASE": "<umtri-api-base>"
      }
    }
  }
}
